__doc__='python module for package G4PhysicsLists'

def _cpp_get_lists( with_descr, include_g4ref, include_custom ):
    from ._impl import get_lists
    lines = get_lists( with_descr, include_g4ref, include_custom ).splitlines()
    return [ tuple( e.split('\t') ) for e in lines ] if with_descr else lines

def getAllListNames(include_description = False, include_base = True, include_custom = True):
    base=[]
    custom=[]
    if include_base:
        base = _cpp_get_lists( include_description, True, False )
    if include_custom:
        custom = _cpp_get_lists( include_description, False, True )
    return sorted(base)+sorted(custom)

def listIsCustom(plname):
    return plname.startswith('PL_')

def printAvailableLists():
    print ("Available physics lists (append +TS or +OPTICAL to inject thermal scattering / optical processes):")
    for l,descr in getAllListNames(include_description=True):
        print ("   %s [%s]"%(l,descr))
